const CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l";
const GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];

function polymod(values) {
  let chk = 1;
  for (const v of values) {
    const b = chk >>> 25;
    chk = ((chk & 0x1ffffff) << 5) ^ v;
    for (let i = 0; i < 5; i++) {
      if ((b >> i) & 1) chk ^= GEN[i];
    }
  }
  return chk >>> 0;
}

function hrpExpand(hrp) {
  const out = [];
  for (const c of hrp) out.push(c.charCodeAt(0) >> 5);
  out.push(0);
  for (const c of hrp) out.push(c.charCodeAt(0) & 31);
  return out;
}

function createChecksum(hrp, data, constant) {
  constant = constant === undefined ? 1 : constant;
  const values = hrpExpand(hrp).concat(data);
  const pm = polymod(values.concat([0, 0, 0, 0, 0, 0])) ^ constant;
  const out = [];
  for (let i = 0; i < 6; i++) out.push((pm >> (5 * (5 - i))) & 31);
  return out;
}

// bech32_encode: hrp + '1' + data chars (data = 5-bit values, already including witver etc.)
function bech32Encode(hrp, data, constant) {
  const combined = data.concat(createChecksum(hrp, data, constant));
  return hrp + "1" + combined.map((d) => CHARSET[d]).join("");
}

function verifyChecksum(hrp, data) {
  return polymod(hrpExpand(hrp).concat(data)) === 1;
}

// convertbits from 8 -> 5 with pad
function convertbits(data, frombits, tobits, pad) {
  let acc = 0, bits = 0;
  const ret = [];
  const maxv = (1 << tobits) - 1;
  const maxacc = (1 << (frombits + tobits)) - 1;
  for (const value of data) {
    if (value < 0 || value >> frombits) return null;
    acc = ((acc << frombits) | value) & maxacc;
    bits += frombits;
    while (bits >= tobits) {
      bits -= tobits;
      ret.push((acc >> bits) & maxv);
    }
  }
  if (pad) {
    if (bits) ret.push((acc << (tobits - bits)) & maxv);
  } else if (bits >= frombits || ((acc << (tobits - bits)) & maxv)) {
    return null;
  }
  return ret;
}

function segwitEncode(hrp, witver, witprog, constant) {
  const conv = convertbits(witprog, 8, 5, true);
  return bech32Encode(hrp, [witver].concat(conv), constant);
}

module.exports = { CHARSET, polymod, hrpExpand, createChecksum, bech32Encode, verifyChecksum, convertbits, segwitEncode };

